package com.jagan.healthcare.dto;
import jakarta.validation.constraints.*;
public class HospitalRequest { @NotBlank @Size(max=100) private String name; @NotBlank @Size(max=100) private String city; @Size(max=255) private String area; @Size(max=500) private String address; @Size(max=255) private String phone; @Size(max=500) private String specialties; public HospitalRequest(){} public String getName(){return name;} public String getCity(){return city;} public String getArea(){return area;} public String getAddress(){return address;} public String getPhone(){return phone;} public String getSpecialties(){return specialties;} public void setName(String v){name=v;} public void setCity(String v){city=v;} public void setArea(String v){area=v;} public void setAddress(String v){address=v;} public void setPhone(String v){phone=v;} public void setSpecialties(String v){specialties=v;} }
